    'Vitrine de cursos de Perícia Judicial': ['Forensic expertise course showcase', 'Vitrina de cursos de peritaje judicial'],
    'Seção de destaques e cards de cursos': ['Highlights section and course cards', 'Sección de destacados y tarjetas de cursos'],
    'Depoimentos de alunos': ['Student testimonials', 'Testimonios de alumnos'], 'Banco Nacional de Peritos': ['National Experts Database', 'Banco Nacional de Peritos'],
